head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.toDay = '';
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/

scwin.clientnow = new Date();

/* 오늘 날짜를 구한다 */
scwin.curYear = scwin.clientnow.getYear();
scwin.curMonth = (scwin.clientnow.getMonth()) + 1;
scwin.curDay = scwin.clientnow.getDate();
if (scwin.curMonth <= 9) {
    scwin.curMonth = "0" + scwin.curMonth;
}
if (scwin.curDay <= 9) {
    scwin.curDay = "0" + scwin.curDay;
}
scwin.txb_date = scwin.curYear + "" + scwin.curMonth + "" + scwin.curDay;
scwin.toDay = scwin.txb_date;

// 현시각(시분) 20210528
scwin.curHH = scwin.clientnow.getHours();
scwin.curMM = scwin.clientnow.getMinutes();
if (scwin.curHH <= 9) {
    scwin.curHH = "0" + scwin.curHH;
}
if (scwin.curMM <= 9) {
    scwin.curMM = "0" + scwin.curMM;
}
scwin.vNowHHMM = scwin.curHH + "" + scwin.curMM;

///////// 2. 초기화 영역 /////////
scwin.onpageload = function() {
};

scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
scwin.MxDataSet_OnLoadCompleted = function(rowcount) {
    try {
        textbox_1.setValue("총 " + rowcount + "건");
        // CloseWin(rowcount, MxGrid_1); 
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT10000.MxDataSet_OnLoadCompleted" });
    }
};

scwin.btn_sys_search_onclick = function(e) {
    try {
        scwin.listSync(); // alert();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT10000.btn_sys_search_onclick" });
    }
};

scwin.image_1_onclick = function(e) {
    try {
        if (scwin.toDay === scwin.txb_date) {
            scwin.save();
        } else {
            alert("과거일은 조회만 가능합니다.");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT10000.image_1_onclick" });
    }
};

scwin.MxLogicalTr_save_OnFail = function() {
    try {
        scwin.listSync();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT10000.MxLogicalTr_save_OnFail" });
    }
};

scwin.MxLogicalTr_save_OnSuccess = function() {
    try {
        scwin.listSync();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT10000.MxLogicalTr_save_OnSuccess" });
    }
};

scwin.MxGrid_1_oncheckclick = function(rowIndex, columnIndex, columnId) {
    try {
        if (bCheck !== 0) {
            scwin.chk(col);
            // alert('MxGrid_1.OnCheckClick('+col+','+ colid+','+ bCheck+')');

        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT10000.MxGrid_1_oncheckclick" });
    }
};

scwin.image_2_onclick = function(e) {
    try {
        if (scwin.toDay === scwin.txb_date) {
            if (confirm('really?')) scwin.save2();
        } else {
            alert("과거일은 조회만 가능합니다.");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT10000.image_2_onclick" });
    }
};

scwin.MxGrid_1_OnClick = function(row, colid) {
    try {
        scwin.listSub(MxDataSet.getCellData(row, "CHK_BZ_TP_CD"));
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT10000.MxGrid_1_OnClick" });
    }
};

scwin.btn_cal_onclick = function(e) {
    try {
        popUpCalendar(txb_date_bg, 'tmbDate', 'yyyymmdd'); // alert('image_2.onclick');		
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT10000.btn_cal_onclick" });
    }
};

scwin.image_3_onclick = function(e) {
    try {
        scwin.notEndDocLst();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT10000.image_3_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
