scwin.save = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet_insert",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_insert=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    if (!scwin.cntDatasetRowCheck(MxDataSet)) {
        alert('체크사항이 없습니다');
        return;
    }
    let lastch = "Y"; // 최종업무확인
    let unitCl = 0;
    for (i = 1; i <= MxDataSet.CountRow; i++) {

        if (MxDataSet.getCellData(i, "CHK_FLAG") === 1) {
            unitCl = i;
        }
    }
    if (unitCl !== 0) {

        MxDataSet.addRow();
        // alert("단위업무마감을 시작합니다.");

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        /*ORG SRC: MxDataSet.NameValue(MxDataSet.RowPosition, "BAS_DD") = MxDataSet.NameValue(unitCl, "BAS_DD");*/

        X = MxDataSet.getCellData(unitCl, "BAS_DD"); /*ORG SRC: MxDataSet.NameValue(MxDataSet.RowPosition, "CHK_BZ_TP_CD") = MxDataSet.NameValue(unitCl, "CHK_BZ_TP_CD");*/ X = MxDataSet.getCellData(unitCl, "CHK_BZ_TP_CD"); /*ORG SRC: MxDataSet.NameValue(MxDataSet.RowPosition, "UNIT_BZ_CLS_DDTM") = "99991231000000";*/ X = "99991231000000"; /*ORG SRC: MxDataSet.NameValue(MxDataSet.RowPosition, "CLS_TRANSTR_EMP_NO") = js_emp_no;*/ X = js_emp_no;
    }
    for (k = 1; k <= MxDataSet.CountRow; k++) {

        if (MxDataSet.getCellData(k, "CHK_BZ_TP_CD") === '40' && MxDataSet.getCellData(k, "UNIT_BZ_CLS_DDTM") === "99991231000000") {
            lastch = "N";
            break;
        }
    }
    if (lastch === "Y") {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        MxDataSet.addRow(); /*ORG SRC: MxDataSet.NameValue(MxDataSet.RowPosition, "BAS_DD") = MxDataSet.NameValue(1, "BAS_DD");*/ X = MxDataSet.getCellData(0, "BAS_DD"); /*ORG SRC: MxDataSet.NameValue(MxDataSet.RowPosition, "CHK_BZ_TP_CD") = "40";*/ X = "40"; /*ORG SRC: MxDataSet.NameValue(MxDataSet.RowPosition, "UNIT_BZ_CLS_DDTM") = "99991231000000";*/ X = "99991231000000"; /*ORG SRC: MxDataSet.NameValue(MxDataSet.RowPosition, "CLS_TRANSTR_EMP_NO") = js_emp_no;*/ X = js_emp_no;
    }
    /*

    			MxDataSet_insert.AddRow();

    			MxDataSet_insert.NameValue(1, "BAS_DD") = "20080516";

    			MxDataSet_insert.NameValue(1, "CHK_BZ_TP_CD") = "31";

    			MxDataSet_insert.NameValue(1, "UNIT_BZ_STRT_DDTM") = "20080516090000"

    			MxDataSet_insert.NameValue(1, "UNIT_BZ_CLS_DDTM") = "20080516190000"

    			MxDataSet_insert.NameValue(1, "CLS_TRANSTR_EMP_NO") = "010271";
    */
    // alert(MxDataSet_insert.Text);
    // alert("단위업무의 재시작을 시작합니다\n최종업무가 마감된 경우 최종업무는 개시됩니다");
    MxLogicalTr_save.KeyName = "toinb_dataid4";

    const sbmOptions3 = {
        id : "sbm_MxLogicalTr_save",
        action : "/bzchklist.do",
        ref : "MxDataSet",
        target : "MxLogicalTr_save=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

scwin.save2 = async function() {
    alert("금감원 제출, 코스콤공시전송을 제외한 시작되지 않은 모든 업무를 수동시작합니다.");
    for (i = 1; i <= MxDataSet.CountRow; i++) {

        if (MxDataSet.getCellData(i, "BAS_DD") === "" && MxDataSet.getCellData(i, "CHK_BZ_TP_CD").substring(0, 1) !== '2') {

            if (MxDataSet.getCellData(i, "CHK_BZ_TP_CD") !== '51') {

                // ********************************************************************
                // [WebSquare 전환 추가] 원본 소스와 비교 필요
                // 
                // ********************************************************************

                /*ORG SRC: MxDataSet.NameValue(i, "BAS_DD") = txb_date;*/
                X = scwin.txb_date;
            }
        }
    }

    // alert(MxDataSet.Text);
    MxLogicalTr_save.KeyName = "toinb_dataid4";

    const sbmOptions = {
        id : "sbm_MxLogicalTr_save",
        action : "/bzchklist.do",
        ref : "MxDataSet",
        target : "MxLogicalTr_save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
scwin.chk = function(sval) {

    if (MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") !== '31' && // 유가 공시팀

        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") !== '32' && // 코스닥 공시팀

        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") !== '33' && // 코스닥시장운영팀

        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") !== '34' && // 주식시장운영팀

        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") !== '35' && // ETF시장팀

        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") !== '36' && // 예방감시팀(코스닥)

        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") !== '37' && // 예방감시팀(유가)

        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") !== '39' && // 시장감시3팀(ELW)

        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") !== '38' && // 채권상장공시팀

        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") !== '3A' && // 코넥스상장공시팀

        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") !== '3B' && // 코넥스시장운영팀

        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") !== '3C' && // 예방감시팀(코넥스)

        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") !== '3E' && // 예방감시팀(배출권)

        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") !== '3D' && // ETN시장팀

        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") !== '3F') {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        alert("재시작 대상업무가 아닙니다."); /*ORG SRC: MxDataSet.NameValue(sval, "CHK_FLAG") = 0;*/ X = 0;
        return;
    }

    if (MxDataSet.getCellData(sval, "BAS_DD") === '') {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        alert("업무가 시작되지 않았습니다"); /*ORG SRC: MxDataSet.NameValue(sval, "CHK_FLAG") = 0;*/ X = 0;
        return;
    }

    if (MxDataSet.getCellData(sval, "UNIT_BZ_CLS_DDTM") === '99991231000000') {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        alert("업무가 종료되지 않았습니다."); /*ORG SRC: MxDataSet.NameValue(sval, "CHK_FLAG") = 0;*/ X = 0;
        return;
    }
    for (i = 1; i <= MxDataSet.CountRow; i++) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        if (MxDataSet.getCellData(i, "CHK_FLAG") === 1 && i !== sval) /*ORG SRC: if (MxDataSet.NameValue(i, "CHK_FLAG") == 1 && i != sval) MxDataSet.NameValue(i, "CHK_FLAG") = 0;*/ X = 0;
    }

    MxDataSet.getCellData(sval, "CHK_FLAG") === 1;
};

scwin.cntDatasetRowCheck = function(sval) {
    // 데이터셋의 체크박스 선택이 되어 있는지 확인하여 참,거짓을 넘겨준다.
    cCnt = 0;
    for (let i = 0; i < sval.getRowCount(); i++) {
        // alert(sval.NameValue(i, "CHK_FLAG"));

        if (sval.getCellData(i, "CHK_FLAG") === 1) {
            cCnt++;
        }
    }
    if (cCnt === 0) return false;

    else return true;
};

scwin.notEndDocLst = function() {
    const url = "/jobmonitor/ULDMGT10005.gfm?date=" + tmbDate.getValue();
    const left = screen.width / 2 - document.body.offsetWidth / 2;
    const right = screen.height / 2 - document.body.offsetHeight / 2;

    frame.CreateDialogFrame("virWinNotEndDocLst", url, "미처리 공시 리스트(" + tmbDate.getValue() + ")", left, right, 865, 315, "tool");
};

scwin.MxGrid_1_CanColumnPosChange = function(row, colid) {
    return true;
};

