    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_MxDataSet_insert",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_insert=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions3 = {
        id : "sbm_MxDataSet_select",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_select=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // PanelToGroupBox_02(panel_2);

    // 미승인건 조회 버튼은 18시 이후부터 보이도록 수정 20210528
    if (scwin.vNowHHMM > '1800') {
        image_3.show("");
    } else {
        image_3.hide();
    }
    scwin.listSync();
    // toDaySet(txb_date);

};
